 function renderForm(p,target,notice,reset){const draft=snapshot().drafts[p.id]||{};target.innerHTML=`<article class="tax-form-question" data-problem-id="${esc(p.id)}"><span class="pill">${esc(p.type)}</span><h2>${esc(p.title)}</h2><div class="prompt">${problemHtml(p)}</div>${exhibits(p)}<div class="tax-form-input"></div><div class="qactions"><button class="btn check-one" type="button">채점하기</button></div><div class="inline-notice" role="status"></div><details class="answer-reveal"><summary>정답 · 해설 보기</summary><div><p>${nl(p.explanation)}</p><div class="tax-answer-grid">${p.form.fields.map(f=>`<p>${esc(f.label)}: <strong>${esc((Array.isArray(f.expected)?f.expected:[f.expected]).map(x=>x===true?'체크':x===false?'체크 안 함':typeof x==='number'?x.toLocaleString('ko-KR'):x).join(' 또는 '))}</strong></p>`).join('')}</div>${p.form.variants?.length?'<p class="help">허용 대체답안은 선택한 조건에 맞는 합계까지 일관되게 입력해야 합니다.</p>':''}</div></details></article>`;const fields=SemuonTaxForms.mountFields(target.querySelector('.tax-form-input'),p,{values:draft.form,save:form=>act(()=>store.update(s=>s.drafts[p.id]={form,graded:false}))}),actions=target.querySelector('.qactions');if(!p.source.officialAllAccepted)actions.prepend(...selfButtons(p,notice));actions.querySelector('.check-one').after(resetButton(p,reset));if(p.source.officialAllAccepted)actions.querySelector('.check-one').textContent='참고답안 비교';actions.querySelector('.check-one').onclick=()=>act(()=>{if(p.source.officialAllAccepted){const result=C.grade(p,{form:fields.read()});fields.feedback(result);target.querySelector('.inline-notice').textContent='공식 시험에서는 출제 오류로 전원 정답 처리된 문항입니다. '+(result.correct?'입력값이 학습용 참고답안과 일치합니다.':'참고답안과 다른 항목: '+result.wrongLabels.join(', '))+'. 이 비교는 채점기록·취약점 통계에 반영하지 않습니다.';return}const event=store.record(p,{form:fields.read()});store.update(s=>Object.assign(s.drafts[p.id]||(s.drafts[p.id]={}),{graded:true,correct:event.correct}));fields.feedback(event);notice()});notice();}
