 function renderHistory(){const s=snapshot(),list=s.history.slice().sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)).slice(0,30);$('#history-list').innerHTML=list.length?`<div class="table-scroll"><table><thead><tr><th>문제</th><th>채점 일시</th><th>결과</th><th>기록 관리</th></tr></thead><tbody>${list.map(e=>`<tr><td>${esc(s.items.find(p=>p.id===e.problemId)?.title)}</td><td>${new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',dateStyle:'short',timeStyle:'short'}).format(new Date(e.at))}</td><td>${e.correct?'정답':'오답'}${e.cancelledAt?' · 취소':''}</td><td><button class="btn secondary history-action" data-id="${esc(e.id)}" data-cancelled="${Boolean(e.cancelledAt)}">${e.cancelledAt?'취소 복구':'채점 취소'}</button></td></tr>`).join('')}</tbody></table></div>`:'<p>실제로 채점한 기록이 없습니다.</p>';$$('.history-action').forEach(b=>b.onclick=()=>act(()=>{b.dataset.cancelled==='true'?store.restore(b.dataset.id):store.cancel(b.dataset.id);renderHistory()}))}
 function guide(){content.innerHTML=head('Design Guide Line','공통 개발·디자인 가이드에 따른 세무온의 평면 UI 규칙.')+`<section class="card"><h2>선과 색으로 표현하는 화면</h2><p>배경 #F8F5F1, 카드·입력칸은 밝은 평면 색을 사용합니다. 입체 그림자, 음각, 자동 축소와 눌림 효과를 사용하지 않습니다.</p><div class="guide-colors">${[['바탕','#f8f5f1'],['주요 행동·선택','#155e59'],['강조','#ac6338'],['경계선','#d7cec0']].map(([label,color])=>`<div><div class="swatch" style="background:${color}"></div><p>${label}<br>${color}</p></div>`).join('')}</div></section><section class="card"><h2>글꼴 · 크기</h2><div class="table-scroll"><table><thead><tr><th>용도</th><th>기본값</th><th>설정 범위</th></tr></thead><tbody><tr><td>메뉴·탐색 UI</td><td>10.5pt (14px)</td><td>1~30pt · 소수 직접 입력</td></tr><tr><td>읽기·문제 본문</td><td>12pt (16px)</td><td>1~30pt · 소수 직접 입력</td></tr></tbody></table></div><p>공통 가이드 12절에 따라 영역별 글꼴과 크기를 분리합니다. 1pt = 96/72px로 표시하며, 선택한 작은 크기도 그대로 적용합니다. 설명문은 기본 14px와 사용자 UI 크기 중 큰 값을 사용하고 줄 높이 1.8을 유지합니다.</p></section><section class="card"><h2>메뉴와 버튼</h2><p>PC 메뉴는 왼쪽에 고정합니다. 좁은 화면에서는 왼쪽 메뉴 버튼으로 큰 글자 메뉴를 엽니다. 선택 메뉴는 청록색 채움과 흰 글자, 비선택은 밝은 바탕과 짙은 글자입니다.</p><div class="row"><button class="btn">학습 시작</button><button class="btn secondary">복습하기</button><button class="btn ghost">해설 보기</button><button class="btn" disabled>비활성</button></div></section><section class="card"><h2>학습 블록</h2><p>원문 → 증빙 → 입력 → 채점 → 접힌 정답·해설. 카드 간격 20px, 모서리 12px, 버튼 높이 44px, 눈에 보이는 키보드 포커스를 사용합니다. 날짜는 오른쪽 위 별도 줄에 표시합니다.</p><div class="feedback good">✓ 정답입니다. 실제 채점 결과만 표시합니다.</div><div class="feedback wrong">! 다시 확인할 항목: 거래일자, 세액</div><a href="${href('design-guide.md')}">공통 가이드 원문</a></section>`}
 $('.mobile-menu').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('.mobile-menu').setAttribute('aria-expanded',String(open))};
 // 메뉴 편집(⚙)과 Ctrl+B 메뉴 접기(2026-10-14 회계 학습 센터에서 이식). 화면 설정이므로 학습기록 저장소와 분리해 이 브라우저에만 보관한다.
 (function(){const MENU_KEY='semuon-tax2-ui-menu',SIDEBAR_KEY='semuon-tax2-sidebar-collapsed',DEFAULT=nav.map(n=>n[0]),activeMenu=['progress','map'].includes(page)?'status':page,navBox=$('#app-nav'),links=[...navBox.children],menuId=id=>['map','progress'].includes(id)?'status':id;
  const read=key=>{try{return localStorage.getItem(key)}catch(_){return null}},write=(key,value)=>{try{localStorage.setItem(key,value);return true}catch(_){toast('이 브라우저에서 화면 설정을 저장하지 못했습니다.');return false}};
  const label=id=>nav.find(n=>n[0]===id)?.[2]||id;
  function complete(order,hidden){const seen=new Set(),out=[];[...(Array.isArray(order)?order:[]).map(menuId),...DEFAULT].forEach(id=>{if(DEFAULT.includes(id)&&!hidden.includes(id)&&!seen.has(id)){seen.add(id);out.push(id)}});return out}
  function load(){let v={};try{v=JSON.parse(read(MENU_KEY)||'{}')||{}}catch(_){}const hidden=[...new Set((Array.isArray(v.hiddenMenuIds)?v.hiddenMenuIds:[]).map(menuId))].filter(id=>DEFAULT.includes(id)&&id!==activeMenu);return{order:complete(v.menuOrder,hidden),hidden}}
  function apply({order,hidden}){order.forEach(id=>{const a=links.find(l=>l.dataset.menuId===id);a.hidden=false;navBox.append(a)});hidden.forEach(id=>{const a=links.find(l=>l.dataset.menuId===id);a.hidden=true;navBox.append(a)})}
  apply(load());
  const gear=document.createElement('button');gear.type='button';gear.className='btn secondary menu-settings-button';gear.innerHTML='<span aria-hidden="true">⚙</span> 메뉴 편집';gear.title='메뉴 순서 · 표시 설정';$('.app-sidebar').append(gear);
  const dialog=document.createElement('dialog');dialog.className='menu-settings';dialog.setAttribute('aria-labelledby','menuSettingsTitle');dialog.innerHTML='<header class="menu-settings-head"><h2 id="menuSettingsTitle">메뉴 편집</h2><button class="btn ghost menu-settings-close" type="button" aria-label="닫기">×</button></header><div class="menu-settings-body"><h3>사용 중인 메뉴 <span class="menu-active-count"></span></h3><ol class="menu-order-list"></ol><h3>대기 중인 메뉴 <span class="menu-waiting-count"></span></h3><ul class="menu-waiting-list"></ul></div><footer class="menu-settings-actions"><button class="btn secondary menu-default" type="button">기본 순서</button><button class="btn secondary menu-cancel" type="button">취소</button><button class="btn menu-save" type="button">저장</button></footer>';document.body.append(dialog);
  const orderList=dialog.querySelector('.menu-order-list'),waitingList=dialog.querySelector('.menu-waiting-list');let draft=[],draftHidden=[],dragged=null;
  function render(){orderList.innerHTML=draft.map((id,i)=>`<li class="menu-order-item" draggable="true" data-menu-id="${esc(id)}"><span class="menu-order-number">${i+1}</span><span class="menu-order-label">${esc(label(id))}</span><button class="btn secondary menu-move" type="button" data-dir="-1" aria-label="${esc(label(id))} 위로" ${i?'':'disabled'}>↑</button><button class="btn secondary menu-move" type="button" data-dir="1" aria-label="${esc(label(id))} 아래로" ${i<draft.length-1?'':'disabled'}>↓</button><button class="btn danger menu-delete" type="button" ${id===activeMenu?'disabled title="현재 보고 있는 메뉴는 삭제할 수 없습니다."':''}>삭제</button></li>`).join('');waitingList.innerHTML=draftHidden.length?draftHidden.map(id=>`<li class="menu-waiting" data-menu-id="${esc(id)}"><span>${esc(label(id))}</span><button class="btn secondary menu-restore" type="button">불러오기</button></li>`).join(''):'<li class="menu-waiting-empty">대기 중인 메뉴가 없습니다.</li>';dialog.querySelector('.menu-active-count').textContent=draft.length;dialog.querySelector('.menu-waiting-count').textContent=draftHidden.length}
  gear.onclick=()=>{const v=load();draft=[...v.order];draftHidden=[...v.hidden];render();dialog.showModal()};
  orderList.addEventListener('click',e=>{const item=e.target.closest('.menu-order-item');if(!item)return;const id=item.dataset.menuId,i=draft.indexOf(id);if(e.target.closest('.menu-delete')){draft.splice(i,1);draftHidden.push(id);render()}const move=e.target.closest('.menu-move');if(move){const j=i+Number(move.dataset.dir);[draft[i],draft[j]]=[draft[j],draft[i]];render();orderList.querySelector(`[data-menu-id="${id}"] .menu-move[data-dir="${move.dataset.dir}"]:not(:disabled)`)?.focus()}});
  waitingList.addEventListener('click',e=>{const item=e.target.closest('.menu-waiting');if(!item||!e.target.closest('.menu-restore'))return;draftHidden=draftHidden.filter(id=>id!==item.dataset.menuId);draft.push(item.dataset.menuId);render()});
  orderList.addEventListener('dragstart',e=>{dragged=e.target.closest('.menu-order-item');if(!dragged)return;dragged.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged.dataset.menuId)});
  orderList.addEventListener('dragover',e=>{if(!dragged)return;e.preventDefault();const t=e.target.closest('.menu-order-item');if(!t||t===dragged)return;const after=e.clientY>t.getBoundingClientRect().top+t.offsetHeight/2;orderList.insertBefore(dragged,after?t.nextSibling:t)});
  orderList.addEventListener('dragend',()=>{if(!dragged)return;draft=[...orderList.children].map(li=>li.dataset.menuId);dragged=null;render()});
  dialog.querySelector('.menu-default').onclick=()=>{draft=[...DEFAULT];draftHidden=[];render()};
  dialog.querySelector('.menu-cancel').onclick=dialog.querySelector('.menu-settings-close').onclick=()=>dialog.close();
  dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
  dialog.querySelector('.menu-save').onclick=()=>{const value={menuOrder:draft,hiddenMenuIds:draftHidden,updatedAt:new Date().toISOString()};if(write(MENU_KEY,JSON.stringify(value))){apply(load());dialog.close();toast('메뉴 순서를 저장했습니다.')}};
  const media=matchMedia('(max-width:760px)'),reopen=document.createElement('button');reopen.type='button';reopen.className='btn secondary sidebar-reopen';reopen.innerHTML='☰ 메뉴';reopen.title='메뉴 펼치기 (Ctrl+B)';document.body.append(reopen);
  let collapsed=read(SIDEBAR_KEY)==='1';
  function setCollapsed(value,persist=false){if(persist){collapsed=value;write(SIDEBAR_KEY,value?'1':'0')}const hide=collapsed&&!media.matches;document.documentElement.classList.toggle('sidebar-collapsed',hide);const aside=$('.app-sidebar');aside.inert=hide;hide?aside.setAttribute('aria-hidden','true'):aside.removeAttribute('aria-hidden')}
  reopen.onclick=()=>{setCollapsed(false,true);$('#app-nav a:not([hidden])')?.focus()};
  document.addEventListener('keydown',e=>{if(!e.ctrlKey||e.altKey||e.shiftKey||e.metaKey||e.key.toLowerCase()!=='b'||e.repeat||media.matches||dialog.open)return;if(e.target.closest?.('input,textarea,select,[contenteditable]'))return;e.preventDefault();setCollapsed(!collapsed,true)});
  window.addEventListener('storage',e=>{if(e.key===SIDEBAR_KEY){collapsed=e.newValue==='1';setCollapsed(collapsed)}if(e.key===MENU_KEY)apply(load())});
  media.addEventListener('change',()=>setCollapsed(collapsed));setCollapsed(collapsed);
 })();
